var i=`0647-thiere`;var a=`world-0647`;var n=`SN`;var s=`western-africa`;var r=4;var l=73;var o={en:`Thiéré`,ua:`Тієре`};var g={en:`Thiéré is a Senegal classic prepared with millet, yellow onion, tomato, lamb. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Millet makes the thiéré base; traditionally the grains are hand rolled and often steamed repeatedly.`,ua:`Тієре, страва кухні країни Сенегал зі складниками: пшоно, жовта цибуля, помідор, ягнятина. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Основа тьєре, пшоно; традиційно крупу вручну формують і часто пропарюють кілька разів.`};var m=[{en:`Steam cleaned millet until fluffy, breaking up clumps so it can absorb the vegetable-and-meat sauce when served.`,ua:`Пропарте промите пшоно до пухкої консистенції й розбийте грудочки, щоб крупа вбирала м’ясо-овочеву підливу.`,t:[`basket-steaming`],m:18,i:[[`millet`,350,`g`],[`water`,510,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,200,`g`],[`extra-virgin-olive-oil`,40,`ml`],[`tomato`,250,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 40 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 40 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:40,i:[[`lamb`,580,`g`],[`carrot`,240,`g`],[`white-cabbage`,200,`g`],[`water`,650,`ml`],[`ground-cumin`,4,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`parsley`,18,`g`]]}];var d={slug:i,id:a,country:`SN`,region:s,servings:4,minutes:73,title:o,text:g,steps:m};export{n as country,d as default,a as id,l as minutes,s as region,r as servings,i as slug,m as steps,g as text,o as title};